function onLoad() {
    //Type appropriate comment here, and begin script below
    // console.log("SM OL 1");
    var outcome = g_form.getValue('outcome');

    if (outcome == 'Switch Maintenance') {
        // console.log("SM OL 2");
        g_form.setDisplay('bulk_id.sub_outcome', true);
        g_form.setReadOnly('bulk_id.sub_outcome', true);
        var subOutcome = g_form.getValue('bulk_id.sub_outcome');
        // console.log("SM OL 3");

        if (subOutcome) {
            hideAllFields();
            // console.log("SM OL 4");
            if (subOutcome == 'Pair Trade') {
                g_form.setDisplay('bulk_id.transaction_reference', true);
                g_form.setReadOnly('bulk_id.transaction_reference', true);

                g_form.setDisplay('bulk_id.transaction_type_display', true);
                g_form.setReadOnly('bulk_id.transaction_type_display', true);

                g_form.setDisplay('bulk_id.legacy_status_display', true);
                g_form.setReadOnly('bulk_id.legacy_status_display', true);

                g_form.setDisplay('bulk_id.pair_switch_reference', false);
                g_form.setDisplay('bulk_id.switch_counterparty_code', false);

            } else if (subOutcome == 'De-Pair Trade') {
                g_form.setDisplay('bulk_id.pair_switch_reference', true);
                g_form.setReadOnly('bulk_id.pair_switch_reference', true);

                g_form.setDisplay('bulk_id.transaction_reference', false);
                g_form.setDisplay('bulk_id.transaction_type_display', false);
                g_form.setDisplay('bulk_id.legacy_status_display', false);
                g_form.setDisplay('bulk_id.switch_counterparty_code', false);

            } else if (subOutcome == 'Convert to Non-Switching Trade') {
                // console.log("SM OL 5");
                g_form.setDisplay('bulk_id.switch_counterparty_code', true);
                g_form.setReadOnly('bulk_id.switch_counterparty_code', true);

                g_form.setDisplay('bulk_id.pair_switch_reference', false);
                g_form.setDisplay('bulk_id.transaction_reference', false);
                g_form.setDisplay('bulk_id.transaction_type_display', false);
                g_form.setDisplay('bulk_id.legacy_status_display', false);

            }

            // var multipleMaker = g_scratchpad.multipleMaker;
            // if ((g_form.getValue('trade_task_type') == 'Maker' && (g_form.getValue('state') == '3' || (g_form.getValue('state') == '2' && multipleMaker == true))) || g_form.getValue('trade_task_type') == 'Checker') {
            //     g_form.setDisplay('decision', false);
            // 	console.log("SM OL 6");

            //     if (subOutcome == 'Pair Trade') {
            //         g_form.setDisplay('bulk_id.transaction_reference', true);
            //         g_form.setReadOnly('bulk_id.transaction_reference', true);

            //         g_form.setDisplay('bulk_id.transaction_type_display', true);
            //         g_form.setReadOnly('bulk_id.transaction_type_display', true);

            //         g_form.setDisplay('bulk_id.legacy_status_display', true);
            //         g_form.setReadOnly('bulk_id.legacy_status_display', true);

            //         g_form.setDisplay('bulk_id.pair_switch_reference', false);
            //         g_form.setDisplay('bulk_id.switch_counterparty_code', false);

            //     } else if (subOutcome == 'De-Pair Trade') {
            //         g_form.setDisplay('bulk_id.pair_switch_reference', true);
            //         g_form.setReadOnly('bulk_id.pair_switch_reference', true);

            //         g_form.setDisplay('bulk_id.transaction_reference', false);
            //         g_form.setDisplay('bulk_id.transaction_type_display', false);
            //         g_form.setDisplay('bulk_id.legacy_status_display', false);
            //         g_form.setDisplay('bulk_id.switch_counterparty_code', false);

            //     } else if (subOutcome == 'Convert to Non-Switching Trade') {
            // 		console.log("SM OL 7");
            //         g_form.setDisplay('bulk_id.switch_counterparty_code', true);
            //         g_form.setReadOnly('bulk_id.switch_counterparty_code', true);

            //         g_form.setDisplay('bulk_id.pair_switch_reference', false);
            //         g_form.setDisplay('bulk_id.transaction_reference', false);
            //         g_form.setDisplay('bulk_id.transaction_type_display', false);
            //         g_form.setDisplay('bulk_id.legacy_status_display', false);

            //     }

        //     g_form.setReadOnly('decision', true);
// }
        return;
    } else {
        // console.log("SM OL 8");
        g_form.setDisplay('bulk_id.sub_outcome', false);

        g_form.setDisplay('bulk_id.transaction_reference', false);
        g_form.setDisplay('bulk_id.transaction_type_display', false);
        g_form.setDisplay('bulk_id.legacy_status_display', false);
        g_form.setDisplay('bulk_id.pair_switch_reference', false);
        g_form.setDisplay('bulk_id.switch_counterparty_code', false);
    }
} else {
    // console.log("SM OL 9");
    g_form.setDisplay('bulk_id.sub_outcome', false);
    hideAllFields();
}



function hideAllFields() {
    var fields = getAllFields();
    fields.forEach(function(field) {
        g_form.setDisplay(field, false);
    });
}

function getAllFields() {
    return [
        'bulk_id.transaction_reference', 'bulk_id.transaction_type_display', 'bulk_id.legacy_status_display', 'bulk_id.pair_switch_reference', 'bulk_id.switch_counterparty_code'
    ];
}


}
